var n=`1229-yuca-con-mojo`;var t=`world-1229`;var o=`CU`;var a=`central-america-caribbean`;var s=4;var r=43;var l={en:`Yuca con Mojo`,ua:`Юка з соусом мохо`};var d={en:`Yuca con Mojo is a dish from Cuba featuring cassava root, garlic, red onion, lime juice. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Юка з соусом мохо, страва кухні країни Куба з такими основними складниками: маніок, часник, червона цибуля, сік лайма. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`cassava-root`,950,`g`],[`water`,1300,`ml`],[`table-salt`,9,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,7,`clove`],[`olive-oil`,95,`ml`],[`red-onion`,130,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`lime-juice`,85,`ml`],[`orange-juice`,60,`ml`],[`parsley`,20,`g`]]},{en:`Gently fold the prepared dressing through the assembled vegetables or cooked ingredients until coated.`,ua:`Обережно перемішайте підготовлену заправку з овочами або готовими продуктами до рівномірного покриття.`,t:[`tossing`,`seasoning`],m:3,i:[]}];var g={slug:n,id:t,country:`CU`,region:a,servings:4,minutes:43,title:l,text:d,steps:u};export{o as country,g as default,t as id,r as minutes,a as region,s as servings,n as slug,u as steps,d as text,l as title};